using System;using System.IO;public class MockEngine{public static int Main(string[] args){int position=Array.FindIndex(args,a=>a.StartsWith("/D="));if(position>=0){var normalized=new System.Collections.Generic.List<string>();for(int i=0;i<position;i++)normalized.Add(args[i]);normalized.Add(String.Join(" ",args,position,args.Length-position));args=normalized.ToArray();}string file=Environment.GetEnvironmentVariable("FUSION_INSTALLER_QA_LOG");File.WriteAllLines(file,args);int result=Int32.Parse(Environment.GetEnvironmentVariable("FUSION_INSTALLER_QA_EXIT")??"0");if(result==0){foreach(string arg in args)if(arg.StartsWith("/D=")){string folder=arg.Substring(3);Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"Fusion Launcher.exe"),"fixture");}}return result;}}
